.model small
.stack

.data
    msg db 'Hello World! $'

; segmento de codigo
.code

    ; procedimiento principal main
    main PROC

        ; carga en memoria las variables del segmento de datos
        MOV ax, @data
        MOV ds, ax
        XOR ax,ax

        ; impresion por pantalla
        mov dx, offset msg
        mov ah, 9
        int 21h
        .exit
        
    main ENDP

end main